import os
import queue
import threading
from dataclasses import dataclass
from typing import Callable, Iterable, Optional, Union

from google.cloud import speech


@dataclass
class StreamingRecognitionEvent:
    text: str
    is_final: bool
    stability: Optional[float] = None
    confidence: Optional[float] = None
    language_code: Optional[str] = None


class GoogleStreamingSpeechToText:
    def __init__(
        self,
        *,
        language_code: str = "en-US",
        sample_rate_hertz: int = 16000,
        audio_encoding: speech.RecognitionConfig.AudioEncoding = speech.RecognitionConfig.AudioEncoding.LINEAR16,
        interim_results: bool = True,
        single_utterance: bool = False,
        model: str = "latest_long",
        enable_automatic_punctuation: bool = True,
    ) -> None:
        self._client = speech.SpeechClient()
        self._language_code = language_code
        self._sample_rate_hertz = sample_rate_hertz
        self._audio_encoding = audio_encoding
        self._interim_results = interim_results
        self._single_utterance = single_utterance
        self._model = model
        self._enable_automatic_punctuation = enable_automatic_punctuation

    def _build_config(self) -> speech.StreamingRecognitionConfig:
        recognition_config = speech.RecognitionConfig(
            encoding=self._audio_encoding,
            sample_rate_hertz=self._sample_rate_hertz,
            language_code=self._language_code,
            model=self._model,
            enable_automatic_punctuation=self._enable_automatic_punctuation,
        )
        return speech.StreamingRecognitionConfig(
            config=recognition_config,
            interim_results=self._interim_results,
            single_utterance=self._single_utterance,
        )

    def stream_from_iterable(
        self,
        audio_chunks: Iterable[bytes],
        on_event: Callable[[StreamingRecognitionEvent], None],
    ) -> None:
        config = self._build_config()

        def request_iter():
            for chunk in audio_chunks:
                if chunk:
                    yield speech.StreamingRecognizeRequest(audio_content=chunk)

        responses = self._client.streaming_recognize(config=config, requests=request_iter())

        for response in responses:
            for result in response.results:
                if not result.alternatives:
                    continue
                alt = result.alternatives[0]
                on_event(
                    StreamingRecognitionEvent(
                        text=alt.transcript,
                        is_final=result.is_final,
                        stability=None if result.is_final else float(getattr(result, "stability", 0.0)),
                        confidence=float(alt.confidence) if result.is_final and hasattr(alt, "confidence") else None,
                        language_code=self._language_code,
                    )
                )

    def stream_from_queue(
        self,
        audio_queue: "queue.Queue[Optional[bytes]]",
        on_event: Callable[[StreamingRecognitionEvent], None],
    ) -> None:
        def audio_iter():
            while True:
                chunk = audio_queue.get()
                if chunk is None:
                    break
                if chunk:
                    yield chunk

        self.stream_from_iterable(audio_iter(), on_event)


class ThreadedStreamingSession:
    def __init__(
        self,
        recognizer: Optional[GoogleStreamingSpeechToText] = None,
        on_partial: Optional[Callable[[StreamingRecognitionEvent], None]] = None,
        on_final: Optional[Callable[[StreamingRecognitionEvent], None]] = None,
        max_queue_size: int = 100,
    ) -> None:
        self.recognizer = recognizer or GoogleStreamingSpeechToText()
        self.on_partial = on_partial
        self.on_final = on_final
        self.audio_queue: "queue.Queue[Optional[bytes]]" = queue.Queue(maxsize=max_queue_size)
        self._thread: Optional[threading.Thread] = None
        self._error: Optional[BaseException] = None

    def _dispatch(self, event: StreamingRecognitionEvent) -> None:
        if event.is_final:
            if self.on_final:
                self.on_final(event)
        else:
            if self.on_partial:
                self.on_partial(event)

    def _run(self) -> None:
        try:
            self.recognizer.stream_from_queue(self.audio_queue, self._dispatch)
        except BaseException as exc:
            self._error = exc

    def start(self) -> None:
        if self._thread and self._thread.is_alive():
            return
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()

    def write(self, chunk: Union[bytes, bytearray, memoryview]) -> None:
        self.audio_queue.put(bytes(chunk))

    def close(self) -> None:
        self.audio_queue.put(None)
        if self._thread:
            self._thread.join()
        if self._error:
            raise self._error


def create_google_streaming_stt_session(
    *,
    language_code: str = "en-US",
    sample_rate_hertz: int = 16000,
    on_partial: Optional[Callable[[StreamingRecognitionEvent], None]] = None,
    on_final: Optional[Callable[[StreamingRecognitionEvent], None]] = None,
    model: str = "latest_long",
) -> ThreadedStreamingSession:
    if not os.getenv("GOOGLE_APPLICATION_CREDENTIALS"):
        pass

    recognizer = GoogleStreamingSpeechToText(
        language_code=language_code,
        sample_rate_hertz=sample_rate_hertz,
        model=model,
        interim_results=True,
    )
    session = ThreadedStreamingSession(
        recognizer=recognizer,
        on_partial=on_partial,
        on_final=on_final,
    )
    session.start()
    return session
